// pyvalues.mjs — Python value model for the Node.js migration.
// PyFloat wraps a JS number as a Python float, PyTuple wraps a JS array as a
// Python tuple, and PyDict is an insertion-ordered dict with Python key
// equality (bool IS int, 1 == 1.0, strings distinct from numbers).

export class PyFloat {
  constructor(value) {
    this.value = value;
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

// Normalize a key to a string identity following Python semantics:
// booleans hash as their int value, PyFloats/ints hash numerically equal,
// strings stay distinct from numbers.
function keyId(k) {
  if (typeof k === 'boolean') return 'n:' + (k ? 1 : 0);
  if (typeof k === 'number') return 'n:' + k;
  if (k instanceof PyFloat) return 'n:' + k.value;
  if (typeof k === 'string') return 's:' + k;
  if (k === null || k === undefined) return 'none:';
  throw new TypeError('unhashable key type');
}

export class PyDict {
  constructor(entries) {
    this._map = new Map(); // keyId -> [originalKey, value]
    if (entries) {
      for (const [k, v] of entries) this.set(k, v);
    }
  }

  set(k, v) {
    const id = keyId(k);
    const existing = this._map.get(id);
    if (existing) {
      // Duplicate key: LAST value wins, key keeps FIRST-seen position/object.
      existing[1] = v;
    } else {
      this._map.set(id, [k, v]);
    }
  }

  get(k) {
    const entry = this._map.get(keyId(k));
    return entry ? entry[1] : undefined;
  }

  has(k) {
    return this._map.has(keyId(k));
  }

  keys() {
    return [...this._map.values()].map(([k]) => k);
  }

  values() {
    return [...this._map.values()].map(([, v]) => v);
  }

  items() {
    return [...this._map.values()].map(([k, v]) => new PyTuple([k, v]));
  }

  get size() {
    return this._map.size;
  }
}

// CPython repr(float).
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  // Shortest round-trip digits via toExponential() with no argument.
  const exp = x.toExponential(); // e.g. "1.5e-7", "1e+16"
  const m = /^(-?)(\d)(?:\.(\d+))?e([+-]?\d+)$/.exec(exp);
  const sign = m[1];
  const digits = m[1] !== undefined ? m[2] + (m[3] || '') : '';
  const P = parseInt(m[4], 10); // scientific exponent

  if (P >= 16 || P < -4) {
    // Scientific notation: mantissa is first digit plus '.' + remaining
    // digits only if more than one digit; exponent always signed, >= 2 digits.
    let mantissa = digits[0];
    if (digits.length > 1) mantissa += '.' + digits.slice(1);
    const expSign = P < 0 ? '-' : '+';
    const expDigits = String(Math.abs(P)).padStart(2, '0');
    return sign + mantissa + 'e' + expSign + expDigits;
  }

  // Fixed notation.
  let out;
  if (P >= 0) {
    if (digits.length > P) {
      out = digits.slice(0, P + 1) + '.' + digits.slice(P + 1);
    } else {
      out = digits + '0'.repeat(P + 1 - digits.length) + '.0';
    }
  } else {
    out = '0.' + '0'.repeat(-P - 1) + digits;
  }
  return sign + out;
}

function pyStrRepr(s) {
  // Default quote is '; use " only if the string has ' but not ".
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || (code >= 0x7f && code <= 0xa0)) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function pyRepr(v) {
  if (v instanceof PyFloat) return pyFloatRepr(v.value);
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (typeof v === 'number') return String(v);
  if (v === null || v === undefined) return 'None';
  if (typeof v === 'string') return pyStrRepr(v);
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 0) return '()';
    if (v.items.length === 1) return '(' + pyRepr(v.items[0]) + ',)';
    return '(' + v.items.map(pyRepr).join(', ') + ')';
  }
  if (v instanceof PyDict) {
    if (v.size === 0) return '{}';
    const parts = [];
    for (const item of v.items()) {
      parts.push(pyRepr(item.items[0]) + ': ' + pyRepr(item.items[1]));
    }
    return '{' + parts.join(', ') + '}';
  }
  if (typeof v.__pyRepr__ === 'function') return v.__pyRepr__();
  return String(v);
}

// Python str(): like repr, except a bare string returns itself unquoted.
export function pyStr(v) {
  if (typeof v === 'string') return v;
  return pyRepr(v);
}

export function pyTypeName(v) {
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'number') return 'int';
  if (v instanceof PyFloat) return 'float';
  if (typeof v === 'string') return 'str';
  if (v === null || v === undefined) return 'NoneType';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  return typeof v;
}

// Python isinstance(x, int): bool IS int.
export function isPyInt(v) {
  return typeof v === 'boolean' || typeof v === 'number';
}

export function isPyFloat(v) {
  return v instanceof PyFloat;
}

export function pyNum(v) {
  if (v instanceof PyFloat) return v.value;
  if (typeof v === 'boolean') return v ? 1 : 0;
  return v;
}

// Python %: result takes the sign of b.
export function pyMod(a, b) {
  const r = ((a % b) + b) % b;
  // Avoid -0 for negative b with exact division; Python gives 0 there too
  // for ints, but normalize so integer inputs yield a plain integer result.
  return Object.is(r, -0) ? 0 : r;
}

// Python len(str): Unicode code points.
export function pyLenStr(s) {
  return [...s].length;
}

// pyliteral.mjs — parser for the Python literal subset accepted by eval:
// None, True/False, ints, floats, strings (with Python escapes), lists,
// tuples, and dicts, with arbitrary nesting and whitespace.
// Values are returned in the pyvalues model: floats as PyFloat, tuples as
// PyTuple, dicts as PyDict, ints as JS numbers, strings as JS strings.

import { PyFloat, PyTuple, PyDict } from './pyvalues.mjs';

class Parser {
  constructor(src) {
    this.src = src;
    this.pos = 0;
  }

  error(msg) {
    throw new Error(`invalid literal at position ${this.pos}: ${msg}`);
  }

  skipWs() {
    while (this.pos < this.src.length && /[ \t\n\r\f\v]/.test(this.src[this.pos])) {
      this.pos++;
    }
  }

  peek() {
    return this.src[this.pos];
  }

  parse() {
    this.skipWs();
    const v = this.parseValue();
    this.skipWs();
    if (this.pos !== this.src.length) this.error('unexpected trailing input');
    return v;
  }

  parseValue() {
    this.skipWs();
    const ch = this.peek();
    if (ch === undefined) this.error('unexpected end of input');
    if (ch === '[') return this.parseList();
    if (ch === '(') return this.parseTupleOrGroup();
    if (ch === '{') return this.parseDict();
    if (ch === "'" || ch === '"') return this.parseString();
    if (ch === '-' || ch === '+' || (ch >= '0' && ch <= '9') || ch === '.') {
      return this.parseNumber();
    }
    if (/[A-Za-z_]/.test(ch)) return this.parseName();
    this.error(`unexpected character ${JSON.stringify(ch)}`);
  }

  parseName() {
    const rest = this.src.slice(this.pos);
    if (rest.startsWith('None')) {
      this.pos += 4;
      return null;
    }
    if (rest.startsWith('True')) {
      this.pos += 4;
      return true;
    }
    if (rest.startsWith('False')) {
      this.pos += 5;
      return false;
    }
    this.error('unknown name');
  }

  parseList() {
    this.pos++; // consume '['
    const items = [];
    this.skipWs();
    if (this.peek() === ']') {
      this.pos++;
      return items;
    }
    for (;;) {
      items.push(this.parseValue());
      this.skipWs();
      const ch = this.peek();
      if (ch === ',') {
        this.pos++;
        this.skipWs();
        if (this.peek() === ']') {
          this.pos++;
          return items; // trailing comma
        }
        continue;
      }
      if (ch === ']') {
        this.pos++;
        return items;
      }
      this.error('expected "," or "]" in list');
    }
  }

  parseTupleOrGroup() {
    this.pos++; // consume '('
    this.skipWs();
    if (this.peek() === ')') {
      this.pos++;
      return new PyTuple([]);
    }
    const first = this.parseValue();
    this.skipWs();
    const ch = this.peek();
    if (ch === ')') {
      // Bare parenthesized value with no comma is just grouping.
      this.pos++;
      return first;
    }
    if (ch !== ',') this.error('expected "," or ")" after element');
    const items = [first];
    while (this.peek() === ',') {
      this.pos++;
      this.skipWs();
      if (this.peek() === ')') {
        this.pos++;
        return new PyTuple(items); // trailing comma, e.g. (1,)
      }
      items.push(this.parseValue());
      this.skipWs();
    }
    if (this.peek() !== ')') this.error('expected ")" to close tuple');
    this.pos++;
    return new PyTuple(items);
  }

  parseDict() {
    this.pos++; // consume '{'
    const d = new PyDict();
    this.skipWs();
    if (this.peek() === '}') {
      this.pos++;
      return d;
    }
    for (;;) {
      const k = this.parseValue();
      this.skipWs();
      if (this.peek() !== ':') this.error('expected ":" in dict');
      this.pos++;
      const v = this.parseValue();
      d.set(k, v);
      this.skipWs();
      const ch = this.peek();
      if (ch === ',') {
        this.pos++;
        this.skipWs();
        if (this.peek() === '}') {
          this.pos++;
          return d; // trailing comma
        }
        continue;
      }
      if (ch === '}') {
        this.pos++;
        return d;
      }
      this.error('expected "," or "}" in dict');
    }
  }

  parseString() {
    const quote = this.src[this.pos];
    this.pos++;
    let out = '';
    for (;;) {
      if (this.pos >= this.src.length) this.error('unterminated string');
      const ch = this.src[this.pos];
      if (ch === quote) {
        this.pos++;
        return out;
      }
      if (ch === '\\') {
        this.pos++;
        if (this.pos >= this.src.length) this.error('unterminated escape');
        const e = this.src[this.pos];
        this.pos++;
        switch (e) {
          case '\\': out += '\\'; break;
          case "'": out += "'"; break;
          case '"': out += '"'; break;
          case 'n': out += '\n'; break;
          case 't': out += '\t'; break;
          case 'r': out += '\r'; break;
          case 'a': out += ''; break;
          case 'b': out += '\b'; break;
          case 'f': out += ' '; break;
          case 'v': out += ''; break;
          case '0': out += '\0'; break;
          case 'x': {
            const hex = this.src.substr(this.pos, 2);
            if (!/^[0-9a-fA-F]{2}$/.test(hex)) this.error('bad \\x escape');
            out += String.fromCodePoint(parseInt(hex, 16));
            this.pos += 2;
            break;
          }
          case 'u': {
            const hex = this.src.substr(this.pos, 4);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.error('bad \\u escape');
            out += String.fromCodePoint(parseInt(hex, 16));
            this.pos += 4;
            break;
          }
          case 'U': {
            const hex = this.src.substr(this.pos, 8);
            if (!/^[0-9a-fA-F]{8}$/.test(hex)) this.error('bad \\U escape');
            out += String.fromCodePoint(parseInt(hex, 16));
            this.pos += 8;
            break;
          }
          default:
            // Unknown escapes: Python keeps the backslash (e.g. "\q").
            out += '\\' + e;
        }
        continue;
      }
      out += ch;
      this.pos++;
    }
  }

  parseNumber() {
    const rest = this.src.slice(this.pos);
    // Int part may be empty for forms like .5; exponent is digits[.digits][eE...]
    const m = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/.exec(rest);
    if (!m) this.error('invalid number');
    const tok = m[0];
    this.pos += tok.length;
    if (/[.eE]/.test(tok)) return new PyFloat(parseFloat(tok));
    return parseInt(tok, 10);
  }
}

export function pyEval(src) {
  if (typeof src !== 'string') throw new Error('pyEval expects a string');
  return new Parser(src).parse();
}
